<script lang="ts">
import { getApp } from '#lib/app.svelte.js';
import { Button } from '#lib/components/ui/button/index.js';
import * as Dialog from '#lib/components/ui/dialog/index.js';
import * as Field from '#lib/components/ui/field/index.js';
import { Input } from '#lib/components/ui/input/index.js';
import { Spinner } from '#lib/components/ui/spinner/index.js';
import { errorMessage } from '#lib/stores/actions.svelte.js';

interface Props {
  /** the engine creating the volume */
  engineId: string;
  onClose: () => void;
}

// creates a volume on the engine: a name, or one generated by the engine
let { engineId, onClose }: Props = $props();

const app = getApp();

let name = $state('');
let creating = $state(false);
let error: string | undefined = $state();

async function create(): Promise<void> {
  const connection = app.engines.get(engineId)?.connection;
  if (!connection) {
    error = 'The engine is not available';
    return;
  }
  creating = true;
  error = undefined;
  try {
    await window.createVolume(connection, name.trim() ? { Name: name.trim() } : {});
    onClose();
  } catch (err: unknown) {
    error = errorMessage(err);
  } finally {
    creating = false;
  }
}
</script>

<Dialog.Root
  open
  onOpenChange={(open): void => {
    if (!open) {
      onClose();
    }
  }}>
  <Dialog.Content>
    <Dialog.Header>
      <Dialog.Title>Create a volume</Dialog.Title>
      <Dialog.Description>On {app.engines.label(engineId, engineId)}.</Dialog.Description>
    </Dialog.Header>
    <form
      class="contents"
      onsubmit={(event): void => {
        event.preventDefault();
        create().catch(console.error);
      }}>
      <Dialog.Body>
        <Field.Field>
          <Field.Label for="volume-name">Name</Field.Label>
          <Input id="volume-name" bind:value={name} placeholder="my-volume" />
          <Field.Description>Left empty, the engine generates one.</Field.Description>
        </Field.Field>
        {#if error}
          <Field.Error>{error}</Field.Error>
        {/if}
      </Dialog.Body>
      <Dialog.Footer>
        <Button variant="outline" onclick={onClose}>Cancel</Button>
        <Button type="submit" disabled={creating}>
          {#if creating}
            <Spinner data-icon="inline-start" />
          {/if}
          Create
        </Button>
      </Dialog.Footer>
    </form>
  </Dialog.Content>
</Dialog.Root>
